const staticData = $getWorkflowStaticData('global');
const nowSec = Math.floor(Date.now() / 1000);

if (staticData.lastSeenTs === undefined || staticData.lastSeenTs === null) {
  // First run ever: look back 5 minutes so we don't miss events that fired
  // while this workflow was being set up.
  staticData.lastSeenTs = nowSec - 300;
}

const OVERLAP_SECONDS = 30;
const after = Math.max(0, staticData.lastSeenTs - OVERLAP_SECONDS);

return [
  {
    json: {
      camera: 'frontdoor',
      label: 'person',
      after,
      limit: 50,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

staticData.processedIds = staticData.processedIds || [];

// Flatten HTTP Request output defensively: n8n may split a JSON-array
// response into one item per element, or return the whole array as one item.
const rawItems = $input.all().map((i) => i.json);
let events = [];
for (const item of rawItems) {
  if (Array.isArray(item)) events.push(...item);
  else if (item && typeof item === 'object') events.push(item);
}

// Advance the poll cursor using every fetched event's start_time, even ones
// we don't classify yet, so the window doesn't stall on a persistently-open
// event. The 30s overlap applied in "Build Poll Query" plus id-based dedupe
// downstream means this is safe.
for (const ev of events) {
  const ts = ev.start_time != null ? ev.start_time : 0;
  if (staticData.lastSeenTs === undefined || ts > staticData.lastSeenTs) {
    staticData.lastSeenTs = ts;
  }
}

// Only carry forward COMPLETED events (end_time set) not already processed by id.
const processedSet = new Set(staticData.processedIds);
const newEvents = events
  .filter((ev) => ev && ev.id != null && ev.end_time != null && !processedSet.has(ev.id))
  .sort((a, b) => (a.start_time || 0) - (b.start_time || 0));

// One item per new event -- each becomes a separate "Fetch Timeline" call.
// Downstream nodes must locate the source event via pairedItem, not array
// index/order (see "Fetch Timeline" node notes).
return newEvents.map((ev) => ({ json: ev }));

// --- full-trajectory point-in-polygon classifier ---
// `entered_zone` timeline entries only fire on a zone TRANSITION -- a track
// that is already inside a zone on its very first frame never logs one for
// it. A person leaving from inside the doorway zone, or arriving already
// inside the doorway zone, can log a single (or zero) `entered_zone` entries
// and be structurally indistinguishable from noise. The fix: use every
// timeline entry's `data.box` (visible / entered_zone / gone all carry one),
// compute the bottom-center point Frigate itself uses for zone membership
// ((x + w/2, y + h)), and test it against the REAL zone polygons fetched
// from /api/config -- not a hardcoded x-split, since zone geometry can be
// retuned at any time.

function parseZonePolygons(config) {
  const cam = config && config.cameras && config.cameras.frontdoor;
  const zonesCfg = (cam && cam.zones) || {};
  const detectW = (cam && cam.detect && cam.detect.width) || null;
  const detectH = (cam && cam.detect && cam.detect.height) || null;

  const polygons = {};
  for (const [name, zcfg] of Object.entries(zonesCfg)) {
    const coordStr = zcfg && zcfg.coordinates;
    if (!coordStr || typeof coordStr !== 'string') continue;
    const nums = coordStr.split(',').map((s) => Number.parseFloat(s));
    if (nums.some((n) => Number.isNaN(n))) continue;

    const points = [];
    for (let i = 0; i + 1 < nums.length; i += 2) points.push([nums[i], nums[i + 1]]);

    // Frigate's zone coordinates are normalized (0-1) in most configs, but
    // can be stored as absolute pixels against the camera's `detect`
    // resolution. Detect this from the magnitude rather than assuming.
    const maxVal = Math.max(...nums);
    const isAbsolute = maxVal > 1.5;
    const normPoints = isAbsolute && detectW && detectH
      ? points.map(([x, y]) => [x / detectW, y / detectH])
      : points;

    if (normPoints.length >= 3) polygons[name] = normPoints;
  }
  return polygons;
}

// Standard ray-casting point-in-polygon test.
function pointInPolygon(point, polygon) {
  const [px, py] = point;
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const [xi, yi] = polygon[i];
    const [xj, yj] = polygon[j];
    const intersects = (yi > py) !== (yj > py)
      && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi;
    if (intersects) inside = !inside;
  }
  return inside;
}

function zoneForPoint(point, polygons) {
  for (const [name, poly] of Object.entries(polygons)) {
    if (pointInPolygon(point, poly)) return name;
  }
  return null; // point is outside every configured zone -- not tracked in the sequence
}

// Build the full-trajectory zone sequence from EVERY timeline entry that
// carries a box (visible, entered_zone, gone -- not just entered_zone), then
// collapse consecutive duplicates.
function extractZoneSequence(timelineEntries, polygons) {
  const ordered = (timelineEntries || [])
    .filter((e) => e && e.data && Array.isArray(e.data.box) && e.data.box.length === 4)
    .sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

  const raw = [];
  for (const e of ordered) {
    const [x, y, w, h] = e.data.box;
    const bottomCenter = [x + w / 2, y + h];
    const zone = zoneForPoint(bottomCenter, polygons);
    if (zone) raw.push(zone);
  }

  const collapsed = [];
  for (const z of raw) {
    if (collapsed.length === 0 || collapsed[collapsed.length - 1] !== z) collapsed.push(z);
  }
  return collapsed;
}

function classifyByTransitions(zoneSeq) {
  let delta = 0;
  for (let i = 1; i < zoneSeq.length; i++) {
    const from = zoneSeq[i - 1];
    const to = zoneSeq[i];
    if (from === 'approach' && to === 'doorway') delta += 1;
    else if (from === 'doorway' && to === 'approach') delta -= 1;
  }

  const distinctZones = new Set(zoneSeq).size;
  let label;
  if (distinctZones < 2) label = 'UNCLEAR'; // never crossed -- collapsed sequence is a single zone (or empty)
  else if (delta > 0) label = 'ENTERED';
  else if (delta < 0) label = 'LEFT';
  else label = 'ROUND_TRIP'; // delta==0 but >=2 distinct zones -- e.g. out and back in

  return { delta, label };
}

function applyEvent(state, event, classification, zoneSequence) {
  const next = { ...state };
  next.occupancy = Math.max(0, state.occupancy + classification.delta);

  if (classification.label === 'ENTERED') next.entered = state.entered + 1;
  else if (classification.label === 'LEFT') next.left = state.left + 1;
  else if (classification.label === 'ROUND_TRIP') next.roundTrips = state.roundTrips + 1;
  else next.unclear = state.unclear + 1;

  next.lastEvent = {
    id: event.id != null ? event.id : null,
    label: classification.label,
    delta: classification.delta,
    zoneSequence,
    start_time: event.start_time != null ? event.start_time : null,
    end_time: event.end_time != null ? event.end_time : null,
  };
  return next;
}

function computeConfidence(state) {
  const total = state.entered + state.left + state.roundTrips + state.unclear;
  if (total === 0) return 1;
  const unclearRatio = state.unclear / total;
  return Math.max(0, Math.round((1 - unclearRatio) * 100) / 100);
}

// --- workflow state (n8n static data, persisted across polls) ---
const staticData = $getWorkflowStaticData('global');

staticData.occupancyState = staticData.occupancyState || {
  occupancy: 0,
  entered: 0,
  left: 0,
  roundTrips: 0,
  unclear: 0,
  lastEvent: null,
  manualOverride: null,
};
staticData.processedIds = staticData.processedIds || [];
const MAX_PROCESSED_IDS = 500;

// Zone polygons come from /api/config via the "Fetch Zone Config" node,
// which runs once per poll execution in parallel with the events branch
// (so it is available even when there are zero new events this poll).
// Cache the parsed result in static data as a defensive fallback in case
// that node's output isn't reachable in a given execution context (e.g. a
// future trigger path that doesn't include it).
let polygons;
try {
  const zoneConfigJson = $('Fetch Zone Config').first().json;
  polygons = parseZonePolygons(zoneConfigJson);
  if (Object.keys(polygons).length > 0) {
    staticData.zonePolygons = { fetchedAt: Date.now(), polygons };
  } else if (staticData.zonePolygons && staticData.zonePolygons.polygons) {
    polygons = staticData.zonePolygons.polygons;
  }
} catch (err) {
  polygons = (staticData.zonePolygons && staticData.zonePolygons.polygons) || {};
}

// Pair each timeline HTTP response back to its originating event via
// pairedItem.item, NOT array order. Verified empirically: without
// "fullResponse" on the "Fetch Timeline" node, n8n auto-splits each event's
// N-entry timeline JSON array into N separate items with sequential (bogus)
// pairedItem indices -- silently mismatching timeline entries to the wrong
// event whenever more than one event is in flight in the same poll. With
// fullResponse:true, "Fetch Timeline" emits exactly one output item per input
// item and pairedItem.item correctly indexes back into "Prepare New Events".
const preparedEvents = $('Prepare New Events').all();
const timelineResponses = $input.all();

const results = [];
let state = staticData.occupancyState;

for (const resp of timelineResponses) {
  const srcIdx = resp.pairedItem && resp.pairedItem.item != null ? resp.pairedItem.item : null;
  const ev = srcIdx != null && preparedEvents[srcIdx] ? preparedEvents[srcIdx].json : null;
  if (!ev || ev.id == null) continue; // cannot attribute this response to an event; skip defensively
  if (staticData.processedIds.includes(ev.id)) continue; // already processed (safety net)

  const timelineBody = Array.isArray(resp.json && resp.json.body) ? resp.json.body : [];
  const zoneSequence = extractZoneSequence(timelineBody, polygons);
  const classification = classifyByTransitions(zoneSequence);

  state = applyEvent(state, ev, classification, zoneSequence);
  staticData.processedIds.push(ev.id);

  results.push({
    json: {
      eventId: ev.id,
      label: classification.label,
      delta: classification.delta,
      zoneSequence,
      start_time: ev.start_time,
      end_time: ev.end_time,
      occupancy: state.occupancy,
      entered: state.entered,
      left: state.left,
      roundTrips: state.roundTrips,
      unclear: state.unclear,
      confidence: computeConfidence(state),
      snapshotUrl: `http://FRIGATE_LAN_HOST:5000/api/events/${ev.id}/snapshot.jpg`,
    },
  });
}

staticData.occupancyState = state;

if (staticData.processedIds.length > MAX_PROCESSED_IDS) {
  staticData.processedIds = staticData.processedIds.slice(-MAX_PROCESSED_IDS);
}

return results;

