const staticData = $getWorkflowStaticData('global');
const state = staticData.occupancyState || {
  occupancy: 0,
  entered: 0,
  left: 0,
  roundTrips: 0,
  unclear: 0,
  lastEvent: null,
  manualOverride: null,
};

const total = state.entered + state.left + state.roundTrips + state.unclear;
const confidence = total === 0 ? 1 : Math.max(0, Math.round((1 - state.unclear / total) * 100) / 100);

return [
  {
    json: {
      occupancy: state.occupancy,
      entered: state.entered,
      left: state.left,
      roundTrips: state.roundTrips,
      unclear: state.unclear,
      confidence,
      lastEvent: state.lastEvent,
      manualOverride: state.manualOverride,
      generatedAt: new Date().toISOString(),
    },
  },
];

const staticData = $getWorkflowStaticData('global');
staticData.occupancyState = staticData.occupancyState || {
  occupancy: 0,
  entered: 0,
  left: 0,
  roundTrips: 0,
  unclear: 0,
  lastEvent: null,
  manualOverride: null,
};

const query = ($input.first().json && $input.first().json.query) || {};
const raw = query.count;
const parsed = raw !== undefined ? Number.parseInt(raw, 10) : NaN;

if (raw === undefined || Number.isNaN(parsed)) {
  return [
    {
      json: {
        ok: false,
        error: "Missing or invalid 'count' query parameter. Usage: GET /webhook/occupancy/reset?count=0",
        occupancy: staticData.occupancyState.occupancy,
      },
    },
  ];
}

const floored = Math.max(0, Math.trunc(parsed));
if (String(query.stats || '') === '1') {
  staticData.occupancyState.entered = 0;
  staticData.occupancyState.left = 0;
  staticData.occupancyState.roundTrips = 0;
  staticData.occupancyState.unclear = 0;
  staticData.occupancyState.lastEvent = null;
}
staticData.occupancyState.occupancy = floored;
staticData.occupancyState.manualOverride = { value: floored, at: new Date().toISOString() };

return [
  {
    json: {
      ok: true,
      occupancy: staticData.occupancyState.occupancy,
      entered: staticData.occupancyState.entered,
      left: staticData.occupancyState.left,
      roundTrips: staticData.occupancyState.roundTrips,
      unclear: staticData.occupancyState.unclear,
      manualOverride: staticData.occupancyState.manualOverride,
    },
  },
];
